import json, os, pathlib, shutil, subprocess, sys, tempfile, xml.etree.ElementTree as ET
workspace=pathlib.Path(sys.argv[1]).resolve()
fixture={'tests/test_subagent_profiles.py': '"""Project-defined read-only sub-agent profiles (.mini-code/agents/*.md)."""\n\nfrom pathlib import Path\n\nimport pytest\n\nfrom minicode.subagent_profiles import (\n    AGENT_NAME_RE,\n    RESERVED_AGENT_NAMES,\n    load_agent_profiles,\n    resolve_agent_types,\n)\n\n_VALID_FRONTMATTER = (\n    "---\\n"\n    "name: test-locator\\n"\n    "description: Locate failing tests and their fixtures.\\n"\n    "max_turns: 8\\n"\n    "allowed_tools: read_file, list_files, grep_files, find_symbols\\n"\n    "---\\n"\n    "You are a test-locator agent. Find the test and fixture paths."\n)\n\n\ndef _write(root: Path, name: str, content: str) -> Path:\n    target = root / ".mini-code" / "agents" / name\n    target.parent.mkdir(parents=True, exist_ok=True)\n    target.write_text(content, encoding="utf-8")\n    return target\n\n\ndef test_valid_profile_parses(tmp_path):\n    _write(tmp_path, "test-locator.md", _VALID_FRONTMATTER)\n    loaded, errors = load_agent_profiles(tmp_path)\n    assert errors == []\n    assert set(loaded) == {"test-locator"}\n    entry = loaded["test-locator"]\n    assert entry["max_turns"] == 8\n    assert entry["allowed_tools"] == frozenset(\n        {"read_file", "list_files", "grep_files", "find_symbols"}\n    )\n    assert entry["system_prompt"].startswith("You are a test-locator agent.")\n    assert entry["source"] == "project-profile"\n    assert entry["description"] == "Locate failing tests and their fixtures."\n\n\ndef test_body_without_frontmatter_is_rejected(tmp_path):\n    _write(tmp_path, "no-frontmatter.md", "just a body")\n    loaded, errors = load_agent_profiles(tmp_path)\n    assert loaded == {} and len(errors) == 1\n    assert "no-frontmatter.md" in errors[0]\n\n\ndef test_unclosed_frontmatter_is_rejected(tmp_path):\n    _write(\n        tmp_path,\n        "unclosed.md",\n        _VALID_FRONTMATTER.split("---\\n", 2)[0] + "---\\nname: x\\n",\n    )\n    loaded, errors = load_agent_profiles(tmp_path)\n    assert loaded == {} and errors\n\n\ndef test_malformed_frontmatter_line_is_rejected(tmp_path):\n    _write(\n        tmp_path,\n        "malformed.md",\n        _VALID_FRONTMATTER.replace("max_turns: 8", "max_turns 8"),\n    )\n    loaded, errors = load_agent_profiles(tmp_path)\n    assert loaded == {} and errors\n\n\ndef test_reserved_names_are_rejected(tmp_path):\n    for name in sorted(RESERVED_AGENT_NAMES):\n        _write(\n            tmp_path,\n            f"{name}.md",\n            _VALID_FRONTMATTER.replace("test-locator", name),\n        )\n    loaded, errors = load_agent_profiles(tmp_path)\n    assert loaded == {} and len(errors) == len(RESERVED_AGENT_NAMES)\n\n\ndef test_bad_slug_is_rejected(tmp_path):\n    _write(tmp_path, "badslug.md", _VALID_FRONTMATTER.replace("test-locator", "Bad Slug"))\n    loaded, errors = load_agent_profiles(tmp_path)\n    assert loaded == {} and errors\n\n\ndef test_write_tool_is_rejected(tmp_path):\n    _write(\n        tmp_path,\n        "writer.md",\n        _VALID_FRONTMATTER.replace(\n            "allowed_tools: read_file, list_files, grep_files, find_symbols",\n            "allowed_tools: read_file, edit_file",\n        ),\n    )\n    loaded, errors = load_agent_profiles(tmp_path)\n    assert loaded == {} and any("edit_file" in error for error in errors)\n\n\ndef test_unknown_tool_is_rejected(tmp_path):\n    _write(\n        tmp_path,\n        "ghost-tool.md",\n        _VALID_FRONTMATTER.replace("find_symbols", "not_a_real_tool"),\n    )\n    loaded, errors = load_agent_profiles(tmp_path)\n    assert loaded == {} and any("not_a_real_tool" in error for error in errors)\n\n\ndef test_out_of_range_turns_fail_closed(tmp_path):\n    for value in ("0", "500", "eight", "3.5"):\n        _write(\n            tmp_path,\n            f"turns-{value.replace(\'.\', \'_\')}.md",\n            _VALID_FRONTMATTER.replace("max_turns: 8", f"max_turns: {value}"),\n        )\n    loaded, errors = load_agent_profiles(tmp_path)\n    assert loaded == {} and len(errors) == 4\n\n\ndef test_unknown_frontmatter_key_rejected(tmp_path):\n    _write(\n        tmp_path,\n        "extra.md",\n        _VALID_FRONTMATTER.replace(\n            "max_turns: 8", "max_turns: 8\\nunknown_key: 1"\n        ),\n    )\n    loaded, errors = load_agent_profiles(tmp_path)\n    assert loaded == {} and len(errors) == 1\n\n\ndef test_empty_body_rejected(tmp_path):\n    _write(\n        tmp_path,\n        "nobody.md",\n        _VALID_FRONTMATTER.split("---\\nYou are")[0] + "---\\n   \\n",\n    )\n    loaded, errors = load_agent_profiles(tmp_path)\n    assert loaded == {} and errors\n\n\ndef test_missing_directory_is_empty(tmp_path):\n    loaded, errors = load_agent_profiles(tmp_path)\n    assert loaded == {} and errors == []\n\n\ndef test_non_markdown_files_ignored(tmp_path):\n    directory = tmp_path / ".mini-code" / "agents"\n    directory.mkdir(parents=True)\n    (directory / "notes.txt").write_text("not a profile", encoding="utf-8")\n    loaded, errors = load_agent_profiles(tmp_path)\n    assert loaded == {} and errors == []\n\n\ndef test_mtime_cache_invalidates(tmp_path):\n    target = _write(tmp_path, "test-locator.md", _VALID_FRONTMATTER)\n    first, _ = load_agent_profiles(tmp_path)\n    assert set(first) == {"test-locator"}\n    target.write_text(\n        _VALID_FRONTMATTER.replace("name: test-locator", "name: other-locator"),\n        encoding="utf-8",\n    )\n    second, _ = load_agent_profiles(tmp_path)\n    assert set(second) == {"other-locator"}\n\n\ndef test_builtin_names_win_in_resolution(tmp_path):\n    _write(tmp_path, "ignored.md", "---\\nname: explore\\n---\\nbody")\n    profiles, errors = load_agent_profiles(tmp_path)\n    assert profiles == {} and len(errors) == 1\n    merged = resolve_agent_types(tmp_path)\n    assert merged["explore"] is not None\n    assert "source" not in merged["explore"]\n    assert set(merged) >= {"explore", "plan", "general", "workflow"}\n\n\ndef test_resolution_merges_custom_types(tmp_path):\n    _write(tmp_path, "test-locator.md", _VALID_FRONTMATTER)\n    merged = resolve_agent_types(tmp_path)\n    assert merged["test-locator"]["max_turns"] == 8\n    assert merged["explore"]["max_turns"] == 12\n\n\ndef test_agent_name_re_shape():\n    assert AGENT_NAME_RE.fullmatch("abc") is not None\n    assert AGENT_NAME_RE.fullmatch("test-locator") is not None\n    assert AGENT_NAME_RE.fullmatch("Test") is None\n    assert AGENT_NAME_RE.fullmatch("a") is None  # 总长至少 2\n    assert AGENT_NAME_RE.fullmatch("bad name") is None\n\n\n# ---------------------------------------------------------------------------\n# User-level profile directory (project wins on collision)\n# ---------------------------------------------------------------------------\n\n\ndef _write_user(root: Path, name: str, content: str) -> Path:\n    # user_root is the HOME directory: profiles live under\n    # <home>/.mini-code/agents, mirroring the project layout.\n    target = root / ".mini-code" / "agents" / name\n    target.parent.mkdir(parents=True, exist_ok=True)\n    target.write_text(content, encoding="utf-8")\n    return target\n\n\ndef test_user_level_profile_loads(tmp_path):\n    user_root = tmp_path / "home"\n    _write_user(user_root, "audit-explorer.md", _VALID_FRONTMATTER.replace(\n        "name: test-locator", "name: audit-explorer"\n    ))\n    loaded, errors = load_agent_profiles(tmp_path, user_root=user_root)\n    assert errors == []\n    assert set(loaded) == {"audit-explorer"}\n    merged = resolve_agent_types(tmp_path, user_root=user_root)\n    assert merged["audit-explorer"]["max_turns"] == 8\n\n\ndef test_project_wins_over_user_on_same_name(tmp_path):\n    user_root = tmp_path / "home"\n    _write_user(user_root, "shared-type.md", _VALID_FRONTMATTER.replace(\n        "name: test-locator", "name: shared-type"\n    ).replace("max_turns: 8", "max_turns: 5"))\n    _write(tmp_path, "shared-type.md", _VALID_FRONTMATTER.replace(\n        "name: test-locator", "name: shared-type"\n    ))\n    loaded, errors = load_agent_profiles(tmp_path, user_root=user_root)\n    assert errors == []\n    assert loaded["shared-type"]["max_turns"] == 8  # project value\n\n\ndef test_errors_carry_origin_prefix(tmp_path):\n    user_root = tmp_path / "home"\n    _write_user(user_root, "broken.md", "no frontmatter")\n    loaded, errors = load_agent_profiles(tmp_path, user_root=user_root)\n    assert loaded == {}\n    assert len(errors) == 1\n    assert "user:broken.md" in errors[0]\n\n\ndef test_both_roots_merge(tmp_path):\n    user_root = tmp_path / "home"\n    _write_user(user_root, "user-type.md", _VALID_FRONTMATTER.replace(\n        "name: test-locator", "name: user-type"\n    ))\n    _write(tmp_path, "project-type.md", _VALID_FRONTMATTER.replace(\n        "name: test-locator", "name: project-type"\n    ))\n    loaded, errors = load_agent_profiles(tmp_path, user_root=user_root)\n    assert errors == []\n    assert set(loaded) == {"user-type", "project-type"}\n\n\ndef test_default_user_root_is_home(tmp_path, monkeypatch):\n    monkeypatch.setattr("minicode.subagent_profiles.Path.home", lambda: tmp_path)\n    _write_user(tmp_path, "home-type.md", _VALID_FRONTMATTER.replace(\n        "name: test-locator", "name: home-type"\n    ))\n    loaded, errors = load_agent_profiles(tmp_path)\n    assert errors == []\n    assert set(loaded) == {"home-type"}\n\n\n# ---------------------------------------------------------------------------\n# Task 2: closed typed contracts accept project-defined agent types\n# ---------------------------------------------------------------------------\n\n\ndef test_result_contract_accepts_custom_agent_type():\n    from minicode.subagent_result import project_subagent_result\n\n    result = project_subagent_result(\n        None,\n        subagent_id="sub_" + "1" * 32,\n        agent_type="test-locator",\n        outcome="completed",\n        fallback_summary="found it",\n        partial=False,\n    )\n    assert result["contractStatus"] == "fallback"\n\n\ndef test_result_contract_still_rejects_bad_type_names():\n    from minicode.subagent_result import project_subagent_result\n\n    with pytest.raises(ValueError):\n        project_subagent_result(\n            None,\n            subagent_id="sub_" + "1" * 32,\n            agent_type="bad name; drop",\n            outcome="completed",\n            fallback_summary="x",\n            partial=False,\n        )\n\n\ndef test_model_routing_inherits_for_custom_type():\n    from minicode.subagent_model_routing import resolve_subagent_model_route\n\n    route = resolve_subagent_model_route(\n        {"model": "parent-model"}, "test-locator"\n    )\n    assert route.provider == "inherit"\n    assert route.model == "parent-model"\n\n\ndef test_observation_payload_accepts_custom_agent_type():\n    from minicode.subagent_observation import project_subagent_event\n\n    payload = project_subagent_event(\n        subagent_id="sub_" + "1" * 32,\n        agent_type="test-locator",\n        outcome="completed",\n        model_turns=3,\n        tool_calls=5,\n        duration_ms=1200,\n        max_turns=8,\n        result_contract_status="reported",\n        result_truncated=False,\n    )\n    assert payload is not None\n    assert payload["agentType"] == "test-locator"\n\n\n# ---------------------------------------------------------------------------\n# Task 3: task dispatch accepts project-defined types\n# ---------------------------------------------------------------------------\n\n_IMPORTS_DONE = False\n\n\ndef _dispatch_imports():\n    global _IMPORTS_DONE\n    if not _IMPORTS_DONE:\n        import minicode.tools.task as task_mod\n        from minicode.task_outcome import canonicalize_task_outcome\n        from minicode.tooling import ToolContext\n        from minicode.tools.task import task_tool\n\n        globals()["task_module"] = task_mod\n        globals()["canonicalize_task_outcome"] = canonicalize_task_outcome\n        globals()["ToolContext"] = ToolContext\n        globals()["task_tool"] = task_tool\n        _IMPORTS_DONE = True\n\n\ndef test_run_dispatches_custom_profile_type(tmp_path, monkeypatch):\n    _dispatch_imports()\n    _write(tmp_path, "test-locator.md", _VALID_FRONTMATTER)\n    captured: dict = {}\n\n    def fake_run_agent_turn(**kwargs):\n        captured["messages"] = kwargs["messages"]\n        captured["max_steps"] = kwargs["max_steps"]\n        kwargs["outcome_capture"].record(\n            canonicalize_task_outcome("success", 0)\n        )\n        return [{"role": "assistant", "content": "located tests"}]\n\n    monkeypatch.setattr(task_module, "run_agent_turn", fake_run_agent_turn)\n    result = task_tool.run(\n        {\n            "description": "locate tests",\n            "prompt": "find the tests covering billing",\n            "agent_type": "test-locator",\n        },\n        ToolContext(cwd=str(tmp_path), _runtime={"model": "fake"}),\n    )\n    assert result.ok, result.output\n    assert captured["max_steps"] == 8\n    system = captured["messages"][0]["content"].lower()\n    assert "test-locator agent" in system\n\n\ndef test_unknown_type_lists_available_and_load_errors(tmp_path):\n    _dispatch_imports()\n    _write(tmp_path, "broken.md", "no frontmatter")\n    result = task_module._run(\n        {"description": "x", "prompt": "y", "agent_type": "ghost"},\n        ToolContext(cwd=str(tmp_path), _runtime={"model": "fake"}),\n    )\n    assert not result.ok\n    assert "ghost" in result.output\n    assert "broken.md" in result.output\n\n\ndef test_validate_rejects_malformed_type_name():\n    _dispatch_imports()\n    with pytest.raises(ValueError):\n        task_module._validate(\n            {"description": "x", "prompt": "y", "agent_type": "Bad Name"}\n        )\n\n\ndef test_custom_type_is_concurrency_safe_and_read_only():\n    _dispatch_imports()\n    assert task_module._call_is_concurrency_safe(\n        {"agent_type": "test-locator"}\n    )\n    assert not task_module._call_is_concurrency_safe(\n        {"agent_type": "general"}\n    )\n    profile = task_module._capability_for(\n        {"description": "x", "prompt": "y", "agent_type": "test-locator"}\n    )\n    assert profile.effects.read_only is True\n\n\n# ---------------------------------------------------------------------------\n# Task 4: per-turn dynamic task-tool description and schema enum\n# ---------------------------------------------------------------------------\n\n\ndef test_task_tool_description_lists_custom_type(tmp_path):\n    _dispatch_imports()\n    _write(tmp_path, "test-locator.md", _VALID_FRONTMATTER)\n    dynamic = task_module.build_task_tool_for_project(str(tmp_path))\n    assert "test-locator" in dynamic.description\n    assert "Locate failing tests and their fixtures." in dynamic.description\n    enum = dynamic.input_schema["properties"]["agent_type"]["enum"]\n    assert "test-locator" in enum and "workflow" in enum\n    baseline = task_module.build_task_tool_for_project("/tmp")\n    assert "test-locator" not in baseline.description\n    baseline_enum = baseline.input_schema["properties"]["agent_type"]["enum"]\n    assert baseline_enum == ["explore", "plan", "general", "workflow"]\n\n\ndef test_registry_uses_dynamic_task_tool(tmp_path):\n    _dispatch_imports()\n    from minicode.tools import create_default_tool_registry\n\n    _write(tmp_path, "test-locator.md", _VALID_FRONTMATTER)\n    registry = create_default_tool_registry(\n        str(tmp_path),\n        include_mcp=False,\n        task_tool_definition=task_module.build_task_tool_for_project(str(tmp_path)),\n    )\n    assert "test-locator" in registry.find("task").description\n\n\n# ---------------------------------------------------------------------------\n# Task 5: end-to-end — real filtered registry and loop boundaries\n# ---------------------------------------------------------------------------\n\n\ndef test_custom_type_filtered_registry_has_only_whitelisted_tools(tmp_path):\n    _dispatch_imports()\n    from minicode.tools import create_default_tool_registry\n\n    _write(tmp_path, "test-locator.md", _VALID_FRONTMATTER)\n    merged = resolve_agent_types(tmp_path)\n    allowed = merged["test-locator"]["allowed_tools"]\n    full_tools = create_default_tool_registry(str(tmp_path), include_mcp=False)\n    child = full_tools.filtered(lambda tool: tool.name in allowed)\n    names = {tool.name for tool in child.list()}\n    assert {"grep_files", "read_file"} <= names\n    assert "edit_file" not in names\n    assert "write_file" not in names\n    assert "task" not in names\n\n\ndef test_spawn_rejected_for_custom_type(tmp_path):\n    _dispatch_imports()\n    _write(tmp_path, "test-locator.md", _VALID_FRONTMATTER)\n    with pytest.raises(ValueError, match="read-only explore or plan"):\n        task_module._validate(\n            {\n                "action": "spawn",\n                "description": "locate tests",\n                "prompt": "find tests",\n                "agent_type": "test-locator",\n            }\n        )\n\n\ndef test_continuation_rejected_for_custom_type(tmp_path):\n    _dispatch_imports()\n    _write(tmp_path, "test-locator.md", _VALID_FRONTMATTER)\n    with pytest.raises(ValueError, match="read-only"):\n        task_module._validate(\n            {\n                "description": "follow-up",\n                "prompt": "which test?",\n                "agent_type": "test-locator",\n                "continue_subagent_id": "sub_" + "1" * 32,\n            }\n        )\n\n\ndef test_custom_type_real_loop_round_trip(tmp_path, monkeypatch):\n    _dispatch_imports()\n    from minicode.tools.task import _run as task_run\n\n    _write(tmp_path, "test-locator.md", _VALID_FRONTMATTER)\n    (tmp_path / "needle.txt").write_text("found-it", encoding="utf-8")\n\n    class _ScriptedModel:\n        def __init__(self, steps):\n            self._steps = steps\n            self.calls = 0\n\n        def next(self, messages, on_stream_chunk=None):\n            step = self._steps[self.calls]\n            self.calls += 1\n            return step\n\n    from minicode.types import AgentStep\n\n    model = _ScriptedModel(\n        [\n            AgentStep(\n                type="tool_calls",\n                calls=[\n                    {\n                        "id": "1",\n                        "toolName": "grep_files",\n                        "input": {"pattern": "found-it", "path": "."},\n                    }\n                ],\n            ),\n            AgentStep(\n                type="assistant",\n                content="<final> needle.txt contains found-it",\n            ),\n        ]\n    )\n\n    import minicode.subagent_model_routing as routing_module\n\n    monkeypatch.setattr(\n        routing_module,\n        "create_subagent_model_adapter",\n        lambda runtime, agent_type, *, tools: model,\n    )\n    result = task_run(\n        {\n            "description": "locate tests",\n            "prompt": "grep for found-it",\n            "agent_type": "test-locator",\n        },\n        ToolContext(cwd=str(tmp_path), _runtime={"model": "fake"}),\n    )\n    assert result.ok, result.output\n    assert "Type: test-locator" in result.output\n    assert "needle.txt contains found-it" in result.output\n    assert "=== SUBAGENT RESULT v1 ===" in result.output\n', 'conftest.py': '"""Pytest collection controls for repository-local legacy smoke scripts."""\n\nfrom __future__ import annotations\n\nimport logging\nimport os\nimport sys\nfrom pathlib import Path\n\nimport pytest\n\nfrom tests.global_state_isolation import (\n    FormalStateChanged,\n    GlobalStateGuard,\n    IsolatedTestHome,\n    assert_minicode_not_preloaded,\n)\n\n\n_REAL_HOME = Path(\n    os.environ.get("MINICODE_PYTEST_REAL_HOME")\n    or os.environ.get("HOME")\n    or Path.home()\n).expanduser().resolve()\nassert_minicode_not_preloaded(sys.modules, real_home=_REAL_HOME)\n_TEST_HOME = IsolatedTestHome.create(real_home=_REAL_HOME, environ=os.environ)\n\n\n_REAL_MINICODE_DIR = _REAL_HOME / ".mini-code"\n_PROTECTED_REAL_PATHS = (\n    _REAL_MINICODE_DIR / "memory" / "memory.json",\n    _REAL_MINICODE_DIR / "memory" / "MEMORY.md",\n    _REAL_MINICODE_DIR / "memory" / "approval_audit.json",\n    _REAL_MINICODE_DIR / "sessions_index.json",\n    _REAL_MINICODE_DIR / ".env",\n    _REAL_MINICODE_DIR / "settings.json",\n    _REAL_MINICODE_DIR / "history.json",\n    _REAL_MINICODE_DIR / "context_state.json",\n    _REAL_MINICODE_DIR / "USER.md",\n    _REAL_MINICODE_DIR / "permissions.json",\n    _REAL_MINICODE_DIR / "mcp.json",\n    _REAL_MINICODE_DIR / "minicode.log",\n    _REAL_MINICODE_DIR / "cybernetic_supervisor.json",\n)\n_REAL_HOME_GUARD = GlobalStateGuard(\n    _PROTECTED_REAL_PATHS,\n    protected_roots=(_REAL_MINICODE_DIR,),\n)\n_REAL_HOME_GUARD_FAILURE: str | None = None\n\n\n# These root-level scripts are manual smoke/integration utilities from earlier\n# development rounds. Normal pytest coverage lives under tests/.\ncollect_ignore = [\n    "smoke_test.py",\n    "test_chinese_input.py",\n    "test_integration.py",\n    "test_optim.py",\n    "test_run.py",\n    "test_state_integration.py",\n    "visual_test.py",\n]\n\ncollect_ignore_glob = [\n    "benchmarks/*.py",\n]\n\n\ndef _reset_imported_process_state() -> None:\n    logger = logging.getLogger("minicode")\n    for handler in logger.handlers[:]:\n        handler.close()\n        logger.removeHandler(handler)\n    history_module = sys.modules.get("minicode.history")\n    if history_module is not None:\n        setattr(history_module, "_history_cache", None)\n    context_module = sys.modules.get("minicode.context_manager")\n    token_cache = getattr(context_module, "_token_cache", None) if context_module else None\n    if isinstance(token_cache, dict):\n        token_cache.clear()\n\n\ndef pytest_sessionstart(session: pytest.Session) -> None:\n    _REAL_HOME_GUARD.capture_start()\n\n\ndef pytest_sessionfinish(session: pytest.Session, exitstatus: int) -> None:\n    global _REAL_HOME_GUARD_FAILURE\n    try:\n        _REAL_HOME_GUARD.assert_unchanged()\n    except FormalStateChanged as exc:\n        _REAL_HOME_GUARD_FAILURE = str(exc)\n        session.exitstatus = pytest.ExitCode.TESTS_FAILED\n\n\ndef pytest_terminal_summary(terminalreporter: pytest.TerminalReporter) -> None:\n    if _REAL_HOME_GUARD_FAILURE:\n        terminalreporter.write_sep("=", "REAL HOME POLLUTION DETECTED")\n        terminalreporter.write_line(_REAL_HOME_GUARD_FAILURE)\n\n\ndef pytest_unconfigure(config: pytest.Config) -> None:\n    _reset_imported_process_state()\n    _TEST_HOME.cleanup()\n\n\n@pytest.fixture(autouse=True)\ndef _isolate_minicode_state_per_test():\n    _reset_imported_process_state()\n    _TEST_HOME.reset()\n    yield\n    _reset_imported_process_state()\n    _TEST_HOME.reset()\n\n\n@pytest.fixture\ndef minicode_test_home() -> Path:\n    return _TEST_HOME.home\n\n\n@pytest.fixture\ndef minicode_real_home() -> Path:\n    return _REAL_HOME\n\n\n@pytest.fixture\ndef memory_manager(tmp_path):\n    """Create a MemoryManager with temporary paths."""\n    from minicode.memory import MemoryManager\n    return MemoryManager(project_root=tmp_path)\n\n\n@pytest.fixture\ndef memory_with_entries(memory_manager):\n    """Create a MemoryManager pre-populated with test entries."""\n    from minicode.memory import MemoryScope\n    entries = [\n        ("project", "architecture", "Uses FastAPI for REST API backend", ["api", "fastapi"]),\n        ("project", "code-pattern", "All functions use snake_case naming", ["convention", "naming"]),\n        ("project", "testing", "Tests use pytest with fixtures", ["test", "pytest"]),\n        ("user", "preference", "Always respond in Chinese", ["language", "chinese"]),\n        ("local", "decision", "Use SQLite for development database", ["database", "sqlite"]),\n    ]\n    for scope, category, content, tags in entries:\n        memory_manager.add_entry(\n            MemoryScope(scope), category, content, tags\n        )\n    return memory_manager\n\n\n@pytest.fixture\ndef mock_memory_search():\n    """Mock search function for testing prompt injection."""\n    def mock_search(query, scope=None, limit=20, min_relevance=0.1):\n        from minicode.memory import MemoryEntry, MemoryScope\n        return [\n            MemoryEntry(id="test-1", scope=MemoryScope.PROJECT, category="test", content=f"Mock result for: {query}"),\n        ]\n    return mock_search\n\n\n@pytest.fixture\ndef temp_workspace(tmp_path):\n    """Create a temporary workspace with basic structure."""\n    workspace = tmp_path / "workspace"\n    workspace.mkdir()\n    (workspace / "src").mkdir()\n    (workspace / "tests").mkdir()\n    (workspace / "src" / "main.py").write_text("# Main file\\n")\n    return str(workspace)\n', 'pyproject.toml': '[build-system]\nrequires = ["setuptools>=68", "wheel"]\nbuild-backend = "setuptools.build_meta"\n\n[project]\nname = "minicode-py"\nversion = "0.1.0"\ndescription = "A lightweight terminal coding assistant for local development workflows."\nreadme = "README.md"\nrequires-python = ">=3.11"\ndependencies = [\n    "certifi>=2025.7.14,<2027",\n]\n\n[project.optional-dependencies]\ndev = [\n    "jsonschema>=4.0.0",\n    "pytest>=8.0.0",\n    "ruff>=0.9.0,<1",\n    "setuptools>=68",\n    "wheel",\n]\nmemory-hybrid = [\n    "huggingface-hub>=0.33.4,<1",\n    "numpy>=2.0.0,<3",\n    "onnxruntime>=1.22.0,<2",\n    "tokenizers>=0.21.0,<1",\n]\n\n[project.scripts]\nminicode-py = "minicode.main:main"\nminicode-gateway = "minicode.gateway:run_gateway"\nminicode-cron = "minicode.cron_runner:main"\nminicode-headless = "minicode.headless:main"\nminicode-calibrate-intent = "minicode.intent_semantic_calibration_cli:main"\n\n[tool.pytest.ini_options]\npythonpath = ["."]\ntestpaths = ["tests"]\nmarkers = [\n    "benchmark: performance-oriented regression test",\n]\n\n[tool.setuptools]\npackage-dir = {"" = "."}\n\n[tool.setuptools.packages.find]\nwhere = ["."]\ninclude = ["minicode*"]\nnamespaces = false\n\n[tool.setuptools.package-data]\n"minicode.web" = [\n    "static/*.html",\n    "static/assets/*.css",\n    "static/assets/*.js",\n]\n', 'tests/global_state_isolation.py': '"""Test-only process HOME isolation and formal-state guards."""\n\nfrom __future__ import annotations\n\nimport hashlib\nimport json\nimport os\nimport re\nimport shutil\nimport tempfile\nfrom dataclasses import dataclass\nfrom pathlib import Path\nfrom typing import Any, Iterable, Mapping, MutableMapping\n\n\nTEST_MODEL = "claude-sonnet-4-20250514"\nTEST_AUTH_TOKEN = "pytest-mock-auth-not-a-secret"\n_CREDENTIAL_ENV_NAMES = (\n    "MINI_CODE_PROVIDER",\n    "ANTHROPIC_API_KEY",\n    "ANTHROPIC_AUTH_TOKEN",\n    "ANTHROPIC_BASE_URL",\n    "ANTHROPIC_MODEL",\n    "OPENAI_API_KEY",\n    "OPENAI_API_BASE",\n    "OPENAI_BASE_URL",\n    "OPENROUTER_API_KEY",\n    "OPENROUTER_BASE_URL",\n    "CUSTOM_API_KEY",\n    "CUSTOM_API_BASE_URL",\n    "DEEPSEEK_BASE_URL",\n    "DEEPSEEK_API_KEY",\n)\n\n\ndef _sha256(path: Path) -> str:\n    digest = hashlib.sha256()\n    with path.open("rb") as stream:\n        for chunk in iter(lambda: stream.read(1024 * 1024), b""):\n            digest.update(chunk)\n    return digest.hexdigest()\n\n\ndef snapshot_paths(paths: list[Path] | tuple[Path, ...]) -> dict[str, dict[str, Any]]:\n    """Capture only existence, hash, size, and mtime for protected files."""\n    snapshot: dict[str, dict[str, Any]] = {}\n    for raw_path in paths:\n        path = Path(raw_path).expanduser().absolute()\n        if not path.exists():\n            snapshot[str(path)] = {"exists": False, "sha256": None, "size": None, "mtime_ns": None}\n            continue\n        metadata = path.stat()\n        snapshot[str(path)] = {\n            "exists": True,\n            "sha256": _sha256(path),\n            "size": metadata.st_size,\n            "mtime_ns": metadata.st_mtime_ns,\n        }\n    return snapshot\n\n\ndef compare_snapshots(\n    before: Mapping[str, Mapping[str, Any]],\n    after: Mapping[str, Mapping[str, Any]],\n) -> list[dict[str, Any]]:\n    """Return privacy-safe path/change summaries without file content."""\n    changes: list[dict[str, Any]] = []\n    for path in sorted(set(before) | set(after)):\n        old = before.get(path, {"exists": False})\n        new = after.get(path, {"exists": False})\n        old_exists = bool(old.get("exists"))\n        new_exists = bool(new.get("exists"))\n        kinds: list[str] = []\n        if old_exists != new_exists:\n            kinds.append("created" if new_exists else "deleted")\n        elif old_exists:\n            if old.get("sha256") != new.get("sha256"):\n                kinds.append("content_hash")\n            if old.get("size") != new.get("size"):\n                kinds.append("size")\n            if old.get("mtime_ns") != new.get("mtime_ns"):\n                kinds.append("mtime_ns")\n        if kinds:\n            changes.append({"path": path, "changes": kinds})\n    return changes\n\n\nclass FormalStateChanged(RuntimeError):\n    """Raised when a protected real-home file changes during pytest."""\n\n\nclass GlobalStateGuard:\n    """Hash/stat guard that detects formal-state changes and never rolls back."""\n\n    def __init__(\n        self,\n        protected_paths: list[Path] | tuple[Path, ...],\n        *,\n        protected_roots: list[Path] | tuple[Path, ...] = (),\n    ) -> None:\n        self._protected_paths = tuple(Path(path) for path in protected_paths)\n        self._protected_roots = tuple(Path(path) for path in protected_roots)\n        self._start: dict[str, dict[str, Any]] | None = None\n\n    @property\n    def start_snapshot(self) -> dict[str, dict[str, Any]] | None:\n        return self._start\n\n    def _capture(self, include_paths: Iterable[str] = ()) -> dict[str, dict[str, Any]]:\n        paths = set(self._protected_paths)\n        paths.update(Path(path) for path in include_paths)\n        for root in self._protected_roots:\n            if root.exists():\n                paths.update(path for path in root.rglob("*") if path.is_file())\n        return snapshot_paths(tuple(sorted(paths)))\n\n    def capture_start(self) -> None:\n        self._start = self._capture()\n\n    def assert_unchanged(self) -> None:\n        if self._start is None:\n            raise RuntimeError("formal-state guard start snapshot was not captured")\n        changes = compare_snapshots(self._start, self._capture(self._start))\n        if changes:\n            summary = "; ".join(\n                f"{item[\'path\']} ({\',\'.join(item[\'changes\'])})" for item in changes\n            )\n            raise FormalStateChanged(f"protected real-home state changed: {summary}")\n\n\ndef assert_minicode_not_preloaded(\n    modules: Mapping[str, object],\n    *,\n    real_home: Path,\n) -> None:\n    """Fail before collection if MiniCode observed the real HOME already."""\n    preloaded = sorted(name for name in modules if name == "minicode" or name.startswith("minicode."))\n    if preloaded:\n        raise RuntimeError(\n            "minicode modules were loaded before pytest HOME isolation: "\n            f"{\', \'.join(preloaded)}; protected real home: {real_home}"\n        )\n\n\ndef _safe_worker_name(worker_id: str) -> str:\n    return re.sub(r"[^A-Za-z0-9_.-]", "_", worker_id) or "main"\n\n\n@dataclass\nclass IsolatedTestHome:\n    """One process/xdist-worker HOME whose global state is reset per test."""\n\n    real_home: Path\n    home: Path\n    settings_path: Path\n    environ: MutableMapping[str, str]\n\n    @classmethod\n    def create(\n        cls,\n        *,\n        real_home: Path,\n        environ: MutableMapping[str, str],\n        temp_root: Path | None = None,\n        process_id: int | None = None,\n        worker_id: str | None = None,\n    ) -> "IsolatedTestHome":\n        pid = process_id if process_id is not None else os.getpid()\n        worker = _safe_worker_name(worker_id or environ.get("PYTEST_XDIST_WORKER", "main"))\n        if temp_root is not None:\n            Path(temp_root).mkdir(parents=True, exist_ok=True)\n        home = Path(\n            tempfile.mkdtemp(\n                prefix=f"minicode-pytest-{pid}-{worker}-",\n                dir=str(temp_root) if temp_root is not None else None,\n            )\n        ).resolve()\n        os.chmod(home, 0o700)\n\n        for name in _CREDENTIAL_ENV_NAMES:\n            environ.pop(name, None)\n        environ.update(\n            {\n                "HOME": str(home),\n                "USERPROFILE": str(home),\n                "XDG_CONFIG_HOME": str(home / ".config"),\n                "MINI_CODE_MODEL_MODE": "mock",\n                "MINI_CODE_SHOW_GUIDE": "0",\n                "MINI_CODE_TOOL_PROFILE": "core",\n                "MINI_CODE_MODEL": TEST_MODEL,\n                "ANTHROPIC_AUTH_TOKEN": TEST_AUTH_TOKEN,\n                "MINICODE_PYTEST_REAL_HOME": str(real_home.resolve()),\n                "MINICODE_PYTEST_ISOLATED_HOME": str(home),\n            }\n        )\n        isolation = cls(\n            real_home=real_home.resolve(),\n            home=home,\n            settings_path=home / ".mini-code" / "settings.json",\n            environ=environ,\n        )\n        isolation.reset()\n        return isolation\n\n    def reset(self) -> None:\n        """Restore a deterministic empty MiniCode home while preserving config."""\n        if self.home.exists():\n            for child in self.home.iterdir():\n                if child.is_dir() and not child.is_symlink():\n                    shutil.rmtree(child)\n                else:\n                    child.unlink()\n        else:\n            self.home.mkdir(parents=True, mode=0o700)\n        os.chmod(self.home, 0o700)\n        (self.home / ".config").mkdir(mode=0o700)\n        self.settings_path.parent.mkdir(mode=0o700)\n        self.settings_path.write_text(\n            json.dumps({"model": TEST_MODEL, "toolProfile": "core"}, sort_keys=True) + "\\n",\n            encoding="utf-8",\n        )\n        os.chmod(self.settings_path, 0o600)\n\n    def cleanup(self) -> None:\n        if self.home.exists():\n            shutil.rmtree(self.home)\n'}
selectors=['tests/test_subagent_profiles.py::test_user_level_profile_loads', 'tests/test_subagent_profiles.py::test_project_wins_over_user_on_same_name', 'tests/test_subagent_profiles.py::test_errors_carry_origin_prefix', 'tests/test_subagent_profiles.py::test_both_roots_merge', 'tests/test_subagent_profiles.py::test_default_user_root_is_home']
with tempfile.TemporaryDirectory(prefix="codeloop-private-oracle-") as temp:
    judge=pathlib.Path(temp)/"workspace"
    shutil.copytree(workspace,judge,ignore=shutil.ignore_patterns("__pycache__",".git",".mini-code"))
    for path,text in fixture.items():
        target=judge/path;target.parent.mkdir(parents=True,exist_ok=True);target.write_text(text)
    env={k:v for k,v in os.environ.items() if not any(t in k.upper() for t in ("API_KEY","SECRET","PASSWORD","ACCESS_TOKEN","AUTH_TOKEN"))}
    env["PYTHONPATH"]=str(judge);env["PYTHONDONTWRITEBYTECODE"]="1";env["PYTEST_DISABLE_PLUGIN_AUTOLOAD"]="1"
    receipt=pathlib.Path(temp)/"receipt.xml"
    argv=[sys.executable,"-B","-m","pytest","-q","-p","no:cacheprovider",f"--junitxml={receipt}",*selectors]
    result=subprocess.run(argv,cwd=judge,env=env,capture_output=True,text=True,timeout=170)
    print(result.stdout);print(result.stderr,file=sys.stderr)
    assert result.returncode==0, "historical acceptance failed"
    cases=ET.parse(receipt).getroot().findall(".//testcase")
    assert cases and all(c.find("skipped") is None and c.find("failure") is None and c.find("error") is None for c in cases), "incomplete acceptance"
print("historical acceptance passed")
